async function productForm(p=null){const{data:c}=await supabase.from("categories").select("*").order("name");openModal(`<div class="sheet-head"><h2>${p?"تعديل":"إضافة"} منتج</h2><button data-close>×</button></div><form id="productForm"><label>الاسم<input id="pn" value="${esc(p?.name||"")}" required></label><label>السعر<input id="pp" type="number" min="0" step=".01" value="${p?.price||0}" required></label><label>التصنيف<select id="pc"><option value="">بدون</option>${(c||[]).map(x=>`<option value="${x.id}" ${p?.category_id===x.id?"selected":""}>${esc(x.name)}</option>`).join("")}</select></label><label>نوع التسليم<select id="pd"><option value="automatic">تلقائي</option><option value="manual" ${p?.delivery_type==="manual"?"selected":""}>يدوي</option></select></label><label>حالة المنتج اليدوي<select id="pm"><option value="available">متاح</option><option value="paused" ${p?.manual_availability==="paused"?"selected":""}>موقوف</option><option value="sold_out" ${p?.manual_availability==="sold_out"?"selected":""}>نفد</option></select></label>${imagePicker("productImageFile",p?.image_url||"")}<label>الوصف<textarea id="pdesc">${esc(p?.description||"")}</textarea></label><label>الحقول المطلوبة من العميل<textarea id="prequired" placeholder='مثال: [{"label":"رابط الحساب","type":"url","required":true}]'>${esc(JSON.stringify(p?.required_fields||[]))}</textarea><small>صيغة JSON؛ يمكن إضافة أكثر من حقل.</small><label><input id="pa" type="checkbox" ${p?.is_active!==false?"checked":""}> مفعّل</label><button class="btn primary block">حفظ</button></form>`);$("#productForm").onsubmit=async e=>{e.preventDefault();let imageUrl=p?.image_url||null;const imageFile=$("#productImageFile").files[0];if(imageFile)imageUrl=await uploadFile(imageFile,"products");const payload={name:$("#pn").value.trim(),price:+$("#pp").value,category_id:$("#pc").value||null,delivery_type:$("#pd").value,manual_availability:$("#pm").value,image_url:imageUrl,description:$("#pdesc").value,required_fields:JSON.parse($("#prequired").value||"[]"),is_active:$("#pa").checked};const query=p?supabase.from("products").update(payload).eq("id",p.id):supabase.from("products").insert(payload);const{error}=await query;if(error)return toast(error.message,"error");toast("تم الحفظ");closeModal();adminProducts()}}
